@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_error is not null)
{
    <div class="catalog-error" role="alert">
        <p>Something went wrong: @_error</p>
        <button @onclick="LoadDataAsync">Retry</button>
    </div>
}
else
{
    <div class="catalog-layout">
        <CatalogFilters Categories="_categories"
                        OnFilterApplied="HandleFilterApplied"
                        OnFilterCleared="HandleFilterCleared" />

        <main class="catalog-main">
            <CatalogToolbar SortBy="@_sortBy"
                            Page="_currentPage"
                            PageSize="_pageSize"
                            TotalCount="_totalCount"
                            OnSortChanged="HandleSortChanged" />

            @if (_loading)
            {
                <div class="catalog-loading" aria-live="polite">
                    <p>Loading products...</p>
                </div>
            }
            else if (_products.Count == 0)
            {
                <div class="catalog-empty" aria-live="polite">
                    <p>No products found matching your criteria.</p>
                </div>
            }
            else
            {
                <ProductGrid Products="_products"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />
            }

            @if (_totalPages > 1)
            {
                <CatalogPagination CurrentPage="_currentPage"
                                   TotalPages="_totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        </main>
    </div>
}

@code {
    [Inject] private IProductService ProductService { get; set; } = default!;

    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    private List<Product> _products = [];
    private List<string> _categories = [];
    private ProductFilter _currentFilter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _pageSize = 12;
    private int _totalCount;
    private int _totalPages;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            _error = null;
            _loading = true;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, _pageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            var result = await productsTask;

            _products = result.Items;
            _totalCount = result.TotalCount;
            _totalPages = (int)Math.Ceiling((double)result.TotalCount / _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            _error = null;
            _loading = true;

            var result = await ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, _pageSize);

            _products = result.Items;
            _totalCount = result.TotalCount;
            _totalPages = (int)Math.Ceiling((double)result.TotalCount / _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _currentFilter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleFilterCleared()
    {
        _currentFilter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-filters {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-filters h3 {
    margin-top: 0;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h4 {
    margin-bottom: 0.5rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

.filter-label {
    display: flex;
    flex-direction: column;
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
}

.filter-label input {
    margin-top: 0.25rem;
    padding: 0.35rem;
    width: 100%;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply,
.btn-clear {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-apply {
    background: #0d6efd;
    color: #fff;
}

.btn-apply:hover {
    background: #0b5ed7;
}

.btn-clear {
    background: #6c757d;
    color: #fff;
}

.btn-clear:hover {
    background: #5c636a;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
}

.toolbar-sort {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.toolbar-sort select {
    padding: 0.35rem 0.5rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

.product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

.product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

.product-image {
    height: 160px;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    color: #6c757d;
    padding: 1rem;
    text-align: center;
}

.product-info {
    padding: 0.75rem;
}

.product-name {
    margin: 0 0 0.35rem;
    font-size: 1rem;
}

.product-price {
    margin: 0 0 0.35rem;
    font-weight: 600;
    color: #198754;
}

.product-rating {
    color: #ffc107;
    margin-bottom: 0.35rem;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    border: none;
    border-radius: 4px;
    background: #0d6efd;
    color: #fff;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-to-cart:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-add-to-cart:disabled {
    background: #adb5bd;
    cursor: not-allowed;
}

.catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.35rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

.btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #dee2e6;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-page:hover:not(:disabled) {
    background: #e9ecef;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-page.active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.catalog-loading,
.catalog-empty {
    text-align: center;
    padding: 3rem;
    color: #6c757d;
}

.catalog-error {
    padding: 1.5rem;
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    border-radius: 4px;
    color: #842029;
    text-align: center;
}

.catalog-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    border: none;
    border-radius: 4px;
    background: #dc3545;
    color: #fff;
    cursor: pointer;
}

